import { BriefcaseBusiness, HomeIcon } from "lucide-react";

export default function Header() {
  return (
    <header className="w-full mx-auto">
      <nav className="flex items-center gap-8 px-6 py-6 sm:gap-10 sm:px-8">

        {/* Home */}
        <a
          href="/"
          className="flex items-center gap-2 text-[16px] font-medium text-neutral-950 transition-colors hover:text-neutral-600"
        >
          <HomeIcon
            aria-hidden="true"
            className="h-4 w-4"
            strokeWidth={1.7}
          />

          <span>Home</span>
        </a>

        {/* Work */}
        <a
          href="/work"
          className="flex items-center gap-2 text-[16px] text-neutral-400 transition-colors hover:text-neutral-950"
        >
          <BriefcaseBusiness
            aria-hidden="true"
            className="h-4 w-4"
            strokeWidth={1.7}
          />

          <span>Work</span>
        </a>


      </nav>
    </header>
  );
}
